import hashlib
import hmac
import io
import json
import socket
import threading
import unittest
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.error import HTTPError
from urllib.request import Request, urlopen

MAX_BODY = 256
MAX_CONTEXT_BYTES = 128
MAX_OUTPUT_BYTES = 64
READ_TIMEOUT_SECONDS = 1.0
CLIENT_TIMEOUT_SECONDS = 2.0
AUDIT_FIELDS = {"decision", "caller", "action", "resource", "tenant", "reason"}
SECRET_FIXTURE = "CLASSROOM-SECRET-MUST-NOT-BE-AUDITED"
RAW_PROMPT_FIXTURE = "raw-prompt-must-not-be-audited"
SECRET_ACTION = "SECRET_ACTION"
SECRET_RESOURCE = "SECRET_RESOURCE"
SECRET_TENANT = "SECRET_TENANT"
SECRET_HEADER = "SECRET_HEADER"
SECRET_PROMPT = "SECRET_PROMPT"
ARTIFACT_BYTES = b"project42-classroom-model-artifact-v2"
AUDIT_ALLOWED_VALUES = {
    "decision": {"allow", "deny"},
    "caller": {
        "anonymous", "unrecognized", "unresolved", "alice", "charlie", "dana", "bob",
        "revoked-caller", "expired-caller", "wrong-audience", "operator", "revoked-operator",
    },
    "action": {"call", "manage", "unresolved"},
    "resource": {"model-a", "gateway", "unresolved"},
    "tenant": {"tenant-a", "tenant-b", "unresolved"},
    "reason": {
        "allowlist", "path", "length", "body-limit", "deadline", "incomplete-body",
        "malformed-json", "object-required", "missing", "forged", "revoked", "expired",
        "wrong-audience", "malformed-fields", "policy", "malformed-prompt", "context-limit",
        "rate-limit", "concurrency-limit", "unresolved",
    },
}
AUDIT_FALLBACKS = {
    "decision": "deny",
    "caller": "unrecognized",
    "action": "unresolved",
    "resource": "unresolved",
    "tenant": "unresolved",
    "reason": "unresolved",
}


class FakeClock:
    def __init__(self, value=100.0):
        self.value = value
        self.lock = threading.Lock()

    def monotonic(self):
        with self.lock:
            return self.value

    def advance(self, seconds):
        with self.lock:
            self.value += seconds


class State:
    def __init__(self):
        self.lock = threading.Lock()
        self.backend_calls = 0
        self.audit = []
        self.last_request = {}
        self.clock = FakeClock()
        self.wall_time = 2_000_000_000
        self.slots = threading.BoundedSemaphore(2)
        self.backend_output = "synthetic-response"
        self.backend_hook = None
        self.identities = {
            "alice": {"role": "caller", "tenant": "tenant-a", "audience": "classroom-gateway", "expires": 3_000_000_000, "revoked": False},
            "charlie": {"role": "caller", "tenant": "tenant-a", "audience": "classroom-gateway", "expires": 3_000_000_000, "revoked": False},
            "dana": {"role": "caller", "tenant": "tenant-a", "audience": "classroom-gateway", "expires": 3_000_000_000, "revoked": False},
            "bob": {"role": "caller", "tenant": "tenant-b", "audience": "classroom-gateway", "expires": 3_000_000_000, "revoked": False},
            "revoked-caller": {"role": "caller", "tenant": "tenant-a", "audience": "classroom-gateway", "expires": 3_000_000_000, "revoked": True},
            "expired-caller": {"role": "caller", "tenant": "tenant-a", "audience": "classroom-gateway", "expires": 1, "revoked": False},
            "wrong-audience": {"role": "caller", "tenant": "tenant-a", "audience": "different-service", "expires": 3_000_000_000, "revoked": False},
            "operator": {"role": "operator", "tenant": "tenant-a", "audience": "classroom-gateway", "expires": 3_000_000_000, "revoked": False},
            "revoked-operator": {"role": "operator", "tenant": "tenant-a", "audience": "classroom-gateway", "expires": 3_000_000_000, "revoked": True},
        }


class ClassroomServer(ThreadingHTTPServer):
    allow_reuse_address = True
    daemon_threads = True


class GatewayHandler(BaseHTTPRequestHandler):
    server_version = "ClassroomGateway/2"
    sys_version = ""

    def log_message(self, format_string, *args):
        return

    @property
    def state(self):
        return self.server.state

    def send_json(self, status, value):
        data = json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")
        try:
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Connection", "close")
            self.end_headers()
            self.wfile.write(data)
        except OSError:
            pass
        self.close_connection = True

    @staticmethod
    def safe_audit_value(field, value):
        if isinstance(value, str) and value in AUDIT_ALLOWED_VALUES[field]:
            return value
        return AUDIT_FALLBACKS[field]

    def record(self, decision, caller, action, resource, tenant, reason):
        candidates = {
            "decision": decision,
            "caller": caller,
            "action": action,
            "resource": resource,
            "tenant": tenant,
            "reason": reason,
        }
        event = {
            field: self.safe_audit_value(field, candidates[field])
            for field in AUDIT_FIELDS
        }
        if set(event) != AUDIT_FIELDS:
            raise AssertionError("audit allowlist changed")
        if any(event[field] not in AUDIT_ALLOWED_VALUES[field] for field in AUDIT_FIELDS):
            raise AssertionError("unbounded audit value")
        with self.state.lock:
            self.state.audit.append(event)

    def deny(self, status, error, caller, action, resource, tenant, reason):
        self.record("deny", caller, action, resource, tenant, reason)
        self.send_json(status, {"error": error})

    def lookup_identity(self):
        supplied = self.headers.get("X-Classroom-Identity")
        if supplied is None:
            return "anonymous", None, "missing"
        identity = self.state.identities.get(supplied)
        if identity is None:
            return "unrecognized", None, "forged"
        if identity["revoked"]:
            return supplied, identity, "revoked"
        if identity["expires"] <= self.state.wall_time:
            return supplied, identity, "expired"
        if identity["audience"] != "classroom-gateway":
            return supplied, identity, "wrong-audience"
        return supplied, identity, "ok"

    @staticmethod
    def bounded_utf8(text, byte_limit):
        return text.encode("utf-8")[:byte_limit].decode("utf-8", errors="ignore")

    def do_POST(self):
        self.connection.settimeout(READ_TIMEOUT_SECONDS)
        if self.path not in ("/inference", "/management"):
            self.deny(404, "not-found", "unresolved", "unresolved", "unresolved", "unresolved", "path")
            return

        path_action = "call" if self.path == "/inference" else "manage"
        path_resource = "model-a" if self.path == "/inference" else "gateway"
        raw_length = self.headers.get("Content-Length")
        try:
            length = int(raw_length) if raw_length is not None else -1
        except ValueError:
            length = -1
        if length < 0:
            self.deny(411, "length-required", "unresolved", path_action, path_resource, "unresolved", "length")
            return
        if length > MAX_BODY:
            self.deny(413, "body-limit", "unresolved", path_action, path_resource, "unresolved", "body-limit")
            return
        try:
            body = self.rfile.read(length)
        except (TimeoutError, socket.timeout):
            self.deny(408, "read-timeout", "unresolved", path_action, path_resource, "unresolved", "deadline")
            return
        if len(body) != length:
            self.deny(400, "incomplete-body", "unresolved", path_action, path_resource, "unresolved", "incomplete-body")
            return
        try:
            payload = json.loads(body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self.deny(400, "malformed-json", "unresolved", path_action, path_resource, "unresolved", "malformed-json")
            return
        if not isinstance(payload, dict):
            self.deny(400, "object-required", "unresolved", path_action, path_resource, "unresolved", "object-required")
            return

        caller, identity, identity_status = self.lookup_identity()
        safe_tenant = identity["tenant"] if identity is not None else "unresolved"
        if identity_status != "ok":
            self.deny(401, identity_status, caller, path_action, path_resource, safe_tenant, identity_status)
            return

        action = payload.get("action")
        resource = payload.get("resource")
        tenant = payload.get("tenant")
        if not all(isinstance(item, str) for item in (action, resource, tenant)):
            self.deny(400, "typed-fields-required", caller, path_action, path_resource, safe_tenant, "malformed-fields")
            return

        permission = (identity["role"], self.path, action, resource, tenant)
        allowlist = {
            ("caller", "/inference", "call", "model-a", "tenant-a"),
            ("operator", "/management", "manage", "gateway", "tenant-a"),
        }
        if identity["tenant"] != tenant or permission not in allowlist:
            self.deny(403, "forbidden", caller, path_action, path_resource, safe_tenant, "policy")
            return

        prompt = payload.get("prompt", "")
        if self.path == "/inference":
            if not isinstance(prompt, str):
                self.deny(400, "prompt-string-required", caller, action, resource, safe_tenant, "malformed-prompt")
                return
            try:
                prompt_bytes = prompt.encode("utf-8")
            except UnicodeEncodeError:
                self.deny(400, "malformed-prompt", caller, path_action, path_resource, safe_tenant, "malformed-prompt")
                return
            if len(prompt_bytes) > MAX_CONTEXT_BYTES:
                self.deny(413, "context-limit", caller, path_action, path_resource, safe_tenant, "context-limit")
                return

        now = self.state.clock.monotonic()
        with self.state.lock:
            previous = self.state.last_request.get(caller)
            if previous is not None and now - previous < 1.0:
                rate_denied = True
            else:
                rate_denied = False
                self.state.last_request[caller] = now
        if rate_denied:
            self.deny(429, "rate-limit", caller, action, resource, safe_tenant, "rate-limit")
            return

        if not self.state.slots.acquire(blocking=False):
            with self.state.lock:
                self.state.last_request.pop(caller, None)
            self.deny(429, "concurrency-limit", caller, action, resource, safe_tenant, "concurrency-limit")
            return

        try:
            with self.state.lock:
                self.state.backend_calls += 1
            hook = self.state.backend_hook
            if hook is not None:
                hook()
            self.record("allow", caller, path_action, path_resource, safe_tenant, "allowlist")
            if self.path == "/inference":
                output = self.bounded_utf8(self.state.backend_output, MAX_OUTPUT_BYTES)
                self.send_json(200, {"output": output})
            else:
                self.send_json(200, {"status": "managed"})
        finally:
            self.state.slots.release()


class GatewayTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.server = ClassroomServer(("127.0.0.1", 0), GatewayHandler)
        cls.server.state = State()
        cls.thread = threading.Thread(target=cls.server.serve_forever, name="owned-classroom-server", daemon=True)
        cls.thread.start()
        cls.host, cls.port = cls.server.server_address
        cls.base_url = "http://%s:%d" % (cls.host, cls.port)

    @classmethod
    def tearDownClass(cls):
        cls.server.shutdown()
        cls.server.server_close()
        cls.thread.join(timeout=2)
        if cls.thread.is_alive():
            raise AssertionError("owned server thread did not stop")

    def setUp(self):
        self.state = State()
        self.server.state = self.state

    def post(self, path, identity, payload, raw=None):
        data = raw if raw is not None else json.dumps(payload, separators=(",", ":")).encode("utf-8")
        headers = {"Content-Type": "application/json"}
        if identity is not None:
            headers["X-Classroom-Identity"] = identity
        request = Request(self.base_url + path, data=data, headers=headers, method="POST")
        try:
            with urlopen(request, timeout=CLIENT_TIMEOUT_SECONDS) as response:
                return response.status, json.loads(response.read().decode("utf-8"))
        except HTTPError as error:
            return error.code, json.loads(error.read().decode("utf-8"))

    def inference(self, identity="alice", **changes):
        payload = {"action": "call", "resource": "model-a", "tenant": "tenant-a", "prompt": "hello"}
        payload.update(changes)
        return self.post("/inference", identity, payload)

    def management(self, identity="operator", **changes):
        payload = {"action": "manage", "resource": "gateway", "tenant": "tenant-a"}
        payload.update(changes)
        return self.post("/management", identity, payload)

    def assert_denied_without_dispatch(self, operation, expected_status):
        before = self.state.backend_calls
        status, body = operation()
        self.assertEqual(status, expected_status)
        self.assertIn("error", body)
        self.assertEqual(self.state.backend_calls, before)

    def test_01_allowed_inference(self):
        status, body = self.inference()
        self.assertEqual((status, body), (200, {"output": "synthetic-response"}))
        self.assertEqual(self.state.backend_calls, 1)

    def test_02_allowed_management_is_separate(self):
        status, body = self.management()
        self.assertEqual((status, body), (200, {"status": "managed"}))
        self.assertEqual(self.state.backend_calls, 1)

    def test_03_missing_and_forged_identities(self):
        self.assert_denied_without_dispatch(lambda: self.inference(None), 401)
        self.assert_denied_without_dispatch(lambda: self.inference(SECRET_FIXTURE), 401)

    def test_04_revoked_expired_and_wrong_audience(self):
        self.assert_denied_without_dispatch(lambda: self.inference("revoked-caller"), 401)
        self.assert_denied_without_dispatch(lambda: self.inference("expired-caller"), 401)
        self.assert_denied_without_dispatch(lambda: self.inference("wrong-audience"), 401)

    def test_05_cross_tenant_is_denied(self):
        self.assert_denied_without_dispatch(lambda: self.inference("bob"), 403)
        self.assert_denied_without_dispatch(lambda: self.inference("alice", tenant="tenant-b"), 403)

    def test_06_roles_and_paths_are_separate(self):
        self.assert_denied_without_dispatch(lambda: self.inference("operator"), 403)
        self.assert_denied_without_dispatch(lambda: self.management("alice"), 403)

    def test_07_changed_task_revoked_operator(self):
        self.assert_denied_without_dispatch(lambda: self.management("revoked-operator"), 401)
        self.assertEqual(self.state.audit[-1]["reason"], "revoked")

    def test_08_wrong_action_and_resource_are_denied(self):
        self.assert_denied_without_dispatch(lambda: self.inference(action="manage"), 403)
        self.assert_denied_without_dispatch(lambda: self.inference(resource="model-b"), 403)
        self.assert_denied_without_dispatch(lambda: self.management(resource="model-a"), 403)

    def test_09_body_limit_is_enforced_before_read(self):
        raw = b"x" * (MAX_BODY + 1)
        self.assert_denied_without_dispatch(lambda: self.post("/inference", "alice", None, raw=raw), 413)

    def test_10_malformed_json_is_denied(self):
        self.assert_denied_without_dispatch(lambda: self.post("/inference", "alice", None, raw=b"{"), 400)

    def test_11_arrays_null_and_malformed_types_are_denied(self):
        self.assert_denied_without_dispatch(lambda: self.post("/inference", "alice", []), 400)
        self.assert_denied_without_dispatch(lambda: self.post("/inference", "alice", None, raw=b"null"), 400)
        self.assert_denied_without_dispatch(lambda: self.inference(action=7), 400)
        self.assert_denied_without_dispatch(lambda: self.inference(resource=None), 400)
        self.assert_denied_without_dispatch(lambda: self.inference(tenant=["tenant-a"]), 400)
        self.assert_denied_without_dispatch(lambda: self.inference(prompt={"text": "hello"}), 400)

    def test_12_context_limit_counts_utf8_bytes(self):
        prompt = "é" * 65
        payload = {
            "action": "call",
            "resource": "model-a",
            "tenant": "tenant-a",
            "prompt": prompt,
        }
        raw = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        self.assertLessEqual(len(raw), MAX_BODY)
        self.assertGreater(len(prompt.encode("utf-8")), MAX_CONTEXT_BYTES)
        before = self.state.backend_calls
        status, body = self.post("/inference", "alice", payload, raw=raw)
        self.assertEqual((status, body), (413, {"error": "context-limit"}))
        self.assertEqual(self.state.backend_calls, before)
        self.assertEqual(self.state.audit[-1]["reason"], "context-limit")

    def test_13_output_is_bounded_by_utf8_bytes(self):
        self.state.backend_output = "é" * 100
        status, body = self.inference()
        self.assertEqual(status, 200)
        self.assertLessEqual(len(body["output"].encode("utf-8")), MAX_OUTPUT_BYTES)

    def test_14_rate_limit_uses_injected_monotonic_clock(self):
        self.assertEqual(self.inference()[0], 200)
        before = self.state.backend_calls
        self.assertEqual(self.inference()[0], 429)
        self.assertEqual(self.state.backend_calls, before)
        self.state.clock.advance(1.0)
        self.assertEqual(self.inference()[0], 200)
        self.assertEqual(self.state.backend_calls, before + 1)

    def test_15_concurrency_limit_uses_deterministic_barrier(self):
        two_entered = threading.Event()
        release = threading.Event()
        entered = {"count": 0}
        entered_lock = threading.Lock()

        def hook():
            with entered_lock:
                entered["count"] += 1
                if entered["count"] == 2:
                    two_entered.set()
            if not release.wait(timeout=2):
                raise AssertionError("concurrency release was not signaled")

        self.state.backend_hook = hook
        results = {}

        def worker(name):
            results[name] = self.inference(name)

        first = threading.Thread(target=worker, args=("alice",))
        second = threading.Thread(target=worker, args=("charlie",))
        first.start()
        second.start()
        self.assertTrue(two_entered.wait(timeout=2))
        self.assertEqual(self.state.backend_calls, 2)
        status, body = self.inference("dana")
        self.assertEqual((status, body), (429, {"error": "concurrency-limit"}))
        self.assertEqual(self.state.backend_calls, 2)
        release.set()
        first.join(timeout=2)
        second.join(timeout=2)
        self.assertFalse(first.is_alive())
        self.assertFalse(second.is_alive())
        self.assertEqual(results["alice"][0], 200)
        self.assertEqual(results["charlie"][0], 200)

    def test_16_server_side_slow_body_deadline(self):
        before = self.state.backend_calls
        with socket.create_connection((self.host, self.port), timeout=CLIENT_TIMEOUT_SECONDS) as client:
            client.settimeout(CLIENT_TIMEOUT_SECONDS)
            request = (
                "POST /inference HTTP/1.1\r\n"
                "Host: 127.0.0.1\r\n"
                "Content-Type: application/json\r\n"
                "Content-Length: 100\r\n"
                "X-Classroom-Identity: alice\r\n"
                "Connection: close\r\n\r\n"
                "{"
            ).encode("ascii")
            client.sendall(request)
            response = client.recv(4096)
        self.assertIn(b" 408 ", response)
        self.assertEqual(self.state.backend_calls, before)

    def test_17_audit_allowlist_excludes_header_prompt_and_secret(self):
        status, _ = self.inference(prompt=RAW_PROMPT_FIXTURE)
        self.assertEqual(status, 200)
        before_denials = self.state.backend_calls

        self.assert_denied_without_dispatch(
            lambda: self.inference(action=SECRET_ACTION, resource=SECRET_RESOURCE), 403
        )
        self.assert_denied_without_dispatch(lambda: self.inference(tenant=SECRET_TENANT), 403)
        self.assert_denied_without_dispatch(lambda: self.inference(SECRET_HEADER), 401)
        self.assert_denied_without_dispatch(
            lambda: self.inference(action=SECRET_ACTION, prompt=SECRET_PROMPT), 403
        )
        self.assert_denied_without_dispatch(lambda: self.inference(SECRET_FIXTURE), 401)
        self.assert_denied_without_dispatch(lambda: self.inference(prompt="\ud800"), 400)
        self.assertEqual(self.state.backend_calls, before_denials)

        encoded = json.dumps(self.state.audit, sort_keys=True)
        for forbidden in (
            RAW_PROMPT_FIXTURE,
            SECRET_FIXTURE,
            SECRET_ACTION,
            SECRET_RESOURCE,
            SECRET_TENANT,
            SECRET_HEADER,
            SECRET_PROMPT,
            "\\ud800",
        ):
            self.assertNotIn(forbidden, encoded)
        self.assertIn("unrecognized", encoded)
        self.assertIn("malformed-prompt", encoded)
        self.assertTrue(all(set(event) == AUDIT_FIELDS for event in self.state.audit))
        self.assertTrue(
            all(
                event[field] in AUDIT_ALLOWED_VALUES[field]
                for event in self.state.audit
                for field in AUDIT_FIELDS
            )
        )

    def test_18_unknown_path_is_denied_without_dispatch(self):
        payload = {"action": "call", "resource": "model-a", "tenant": "tenant-a", "prompt": "hello"}
        self.assert_denied_without_dispatch(lambda: self.post("/debug", "alice", payload), 404)


TEST_NAMES = [
    "allowed inference",
    "allowed management is separate",
    "missing and forged identities",
    "revoked expired and wrong audience",
    "cross tenant",
    "separate roles and paths",
    "changed task revoked operator",
    "wrong action and resource",
    "body limit",
    "malformed JSON",
    "arrays null and malformed types",
    "UTF-8 context limit",
    "UTF-8 output limit",
    "injectable monotonic rate limit",
    "deterministic in-flight concurrency limit",
    "server-side body inactivity timeout",
    "safe audit allowlist",
    "unknown path",
]


def artifact_integrity_check():
    locally_computed_digest = hashlib.sha256(ARTIFACT_BYTES).digest()
    original_matches = hmac.compare_digest(hashlib.sha256(ARTIFACT_BYTES).digest(), locally_computed_digest)
    altered_matches = hmac.compare_digest(hashlib.sha256(ARTIFACT_BYTES + b"-altered").digest(), locally_computed_digest)
    if not original_matches or altered_matches:
        raise AssertionError("artifact integrity witness failed")


def main():
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(GatewayTests)
    diagnostics = io.StringIO()
    result = unittest.TextTestRunner(stream=diagnostics, verbosity=2).run(suite)
    if not result.wasSuccessful() or result.testsRun != len(TEST_NAMES):
        print(diagnostics.getvalue(), end="")
        raise SystemExit(1)
    artifact_integrity_check()
    for number, name in enumerate(TEST_NAMES, 1):
        print("PASS %02d %s" % (number, name))
    print("SUMMARY 18 tests passed")
    print("INTEGRITY original=verified altered=rejected")
    print("LOCAL STATUS expected evidence reproduced")
    print("DEPLOYMENT STATUS HOLD")


if __name__ == "__main__":
    main()
